<?php $statusMap=['pending'=>['Pendente','warning'],'confirmed'=>['Confirmado','primary'],'waiting'=>['Check-in / aguardando','warning'],'in_progress'=>['Em atendimento','info'],'completed'=>['Concluído','success'],'cancelled'=>['Cancelado','danger'],'no_show'=>['Não compareceu','secondary']];$barberMode=(bool)($barberMode??false);?>
<div class="section-heading"><div><div class="eyebrow">Atendimento</div><h1>Agenda</h1><p class="text-secondary mb-0"><?=$barberMode?'Agenda da barbearia com check-in, atendimento e comanda integrada.':'Agenda operacional com remarcação, folgas, férias, intervalos e histórico.'?></p></div><div class="d-flex gap-2 flex-wrap"><?php if($barberMode):?><a class="btn btn-outline-primary" href="/barber/queue">Fila / encaixes</a><a class="btn btn-outline-primary" href="/barber/commands">Comandas</a><?php endif;?><a class="btn btn-light" href="/schedule/blocks">Bloqueios</a><?php if(\App\Core\Authorization::allows('agenda.settings.manage')):?><a class="btn btn-light" href="/schedule/settings">Regras</a><?php endif;?><a class="btn btn-primary" href="/appointments/create">+ Novo agendamento</a></div></div>
<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><strong>Atendimentos recentes</strong><span class="text-secondary small"><?=count($appointments)?> registros</span></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data e hora</th><th>Cliente</th><th>Serviço</th><th>Profissional</th><th>Status</th><th><span class="visually-hidden">Ações</span></th></tr></thead><tbody><?php foreach($appointments as $a):$meta=$statusMap[$a['status']]??[$a['status'],'secondary'];?><tr><td><strong><?=htmlspecialchars(date('d/m/Y',strtotime($a['starts_at'])),ENT_QUOTES,'UTF-8')?></strong><div class="text-secondary small"><?=htmlspecialchars(date('H:i',strtotime($a['starts_at'])),ENT_QUOTES,'UTF-8')?>–<?=htmlspecialchars(date('H:i',strtotime($a['ends_at'])),ENT_QUOTES,'UTF-8')?></div><?php if($barberMode&&!empty($a['checked_in_at'])):?><small class="text-success d-block">Check-in <?=date('H:i',strtotime($a['checked_in_at']))?></small><?php endif;?></td><td><strong><?=htmlspecialchars($a['customer_name'],ENT_QUOTES,'UTF-8')?></strong><?php if(!empty($a['vehicle_model'])):?><small class="d-block text-secondary"><?=htmlspecialchars($a['vehicle_model'].(!empty($a['vehicle_plate'])?' • '.$a['vehicle_plate']:''))?></small><?php endif;?></td><td><?=htmlspecialchars($a['service_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($a['professional_name']??'-',ENT_QUOTES,'UTF-8')?></td><td><span class="badge text-bg-<?=$meta[1]?>"><?=$meta[0]?></span><?php if($barberMode&&!empty($a['barber_command_id'])):?><small class="d-block text-secondary mt-1">Comanda #<?=(int)$a['barber_command_id']?> · <?=htmlspecialchars($a['barber_command_status'])?></small><?php endif;?></td><td><div class="d-flex gap-2 justify-content-end align-items-center flex-wrap"><?php if($barberMode&&in_array($a['status'],['confirmed','waiting','in_progress'],true)):?><?php if($a['status']==='confirmed'):?><form method="post" action="/appointments/status"><?=\App\Core\CSRF::field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><input type="hidden" name="status" value="waiting"><button class="btn btn-sm btn-outline-warning">Check-in</button></form><?php endif;?><?php if(in_array($a['status'],['confirmed','waiting'],true)):?><form method="post" action="/appointments/status"><?=\App\Core\CSRF::field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><input type="hidden" name="status" value="in_progress"><button class="btn btn-sm btn-outline-info">Iniciar</button></form><?php endif;?><?php if(!empty($a['barber_command_id'])):?><a class="btn btn-sm btn-success" href="/barber/commands/<?=(int)$a['barber_command_id']?>">Comanda</a><?php else:?><form method="post" action="/barber/commands/open"><?=\App\Core\CSRF::field()?><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><button class="btn btn-sm btn-success">Abrir comanda</button></form><?php endif;?><?php endif;?><a class="btn btn-sm btn-outline-primary" href="/appointments/<?=(int)$a['id']?>/reschedule">Remarcar</a><form method="post" action="/appointments/status" class="d-flex gap-2"><?=\App\Core\CSRF::field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><label class="visually-hidden" for="status-<?=(int)$a['id']?>">Alterar status</label><select id="status-<?=(int)$a['id']?>" name="status" class="form-select form-select-sm"><?php foreach($statusMap as $st=>$label):?><option value="<?=$st?>" <?=$st===$a['status']?'selected':''?>><?=$label[0]?></option><?php endforeach;?></select><button class="btn btn-sm btn-light">Atualizar</button></form></div></td></tr><?php endforeach;?><?php if(!$appointments):?><tr><td colspan="6"><div class="empty-state"><h2 class="h5">Nenhum atendimento por aqui</h2><p>Crie o primeiro horário para começar sua agenda.</p><a href="/appointments/create" class="btn btn-primary">Novo agendamento</a></div></td></tr><?php endif;?></tbody></table></div></div>
